krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_int32 ret = KRB5KDC_ERR_NONE;
    krb5_principal server_princ = NULL;
    krb5_data *hostname = NULL;
    kdc_realm_t *target_realm = NULL;

    /* Check if the request is a referral request */
    if (!request->referral_request) {
        ret = KRB5KDC_ERR_INVALID_REQUEST;
        goto cleanup;
    }

    server_princ = request->client;
    if (!server_princ) {
        ret = KRB5KDC_ERR_MISSING_INFORMATION;
        goto cleanup;
    }

    hostname = krb5_unparse_name(kdc_active_realm->context, server_princ);
    if (!hostname || hostname->length == 0) {
        ret = KRB5_KDC_PATH_NOT_AVAILABLE;
        goto cleanup;
    }

    /* Verify that the hostname is a fully qualified domain name */
    if (!krb5_is_fqdn(kdc_active_realm->context, hostname)) {
        ret = KRB5KDC_ERR_BAD_SERVER_ADDRESS;
        goto cleanup;
    }

    /* Attempt to find the realm associated with the hostname */
    ret = kdc_get_realm_by_hostname(kdc_active_realm->context, hostname, &target_realm);
    if (ret != KRB5KDC_ERR_NONE || !target_realm) {
        ret = KRB5_KDC_PATH_NOT_AVAILABLE;
        goto cleanup;
    }

    /* Ensure that the realm is valid and not empty */
    if (target_realm->realm.length == 0 || target_realm->kdc.length == 0) {
        ret = KRB5KDC_ERR_INVALID_REALM;
        goto cleanup;
    }

    /* Construct the TGT principal for the target realm */
    ret = krb5_build_principal(kdc_active_realm->context, krbtgt_princ, 2, target_realm->realm.data, "krbtgt", target_realm->realm.data, NULL);
    if (ret != KRB5KDC_ERR_NONE) {
        goto cleanup;
    }

cleanup:
    if (hostname) {
        krb5_data_free(hostname);
    }
    return ret;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_error_code ret = KRB5KDC_NO_ERROR;
    krb5_const_realm hostname_realm = NULL;
    krb5_principal tgs_princ = NULL;
    krb5_data *realm_data = NULL;
    krb5_principal server_principal = request->client;

    if (!request || !krbtgt_princ) {
        return KRB5KDC_BAD_ARGS;
    }

    if (!server_principal) {
        return KRB5KDC_NO_PRINCIPAL;
    }

    // Extract the hostname from the server principal
    krb5_data *hostname = krb5_unparse_name(kdc_active_realm->context, server_principal);
    if (!hostname) {
        return KRB5KDC_MALLOC_FAILURE;
    }

    // Check if the hostname has a realm part
    ret = krb5_parse_name(kdc_active_realm->context, hostname->data, &server_principal);
    if (ret) {
        krb5_free_data(kdc_active_realm->context, hostname);
        return ret;
    }

    if (server_principal->realm.length == 0) {
        krb5_free_principal(kdc_active_realm->context, server_principal);
        krb5_free_data(kdc_active_realm->context, hostname);
        return KRB5KDC_BAD_REALM;
    }

    hostname_realm = server_principal->realm.data;

    // Find the realm using the hostname
    kdc_realm_t *target_realm = find_realm_by_name(hostname_realm);
    if (!target_realm) {
        krb5_free_principal(kdc_active_realm->context, server_principal);
        krb5_free_data(kdc_active_realm->context, hostname);
        return KRB5KDC_REALM_NOT_FOUND;
    }

    // Construct TGT principal
    ret = krb5_build_principal(kdc_active_realm->context, &tgs_princ, target_realm->realm.length,
                               target_realm->realm.data, "krbtgt", target_realm->realm.length,
                               target_realm->realm.data, NULL);
    if (ret) {
        krb5_free_principal(kdc_active_realm->context, server_principal);
        krb5_free_data(kdc_active_realm->context, hostname);
        return ret;
    }

    *krbtgt_princ = tgs_princ;
    krb5_free_principal(kdc_active_realm->context, server_principal);
    krb5_free_data(kdc_active_realm->context, hostname);

    return KRB5KDC_NO_ERROR;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_data *hostname = NULL;
    kdc_realm_t *target_realm = NULL;

    if (!request || !krbtgt_princ) {
        return KRB5KDC_ERR_BADOPTION;
    }

    if (!request->is_referral) {
        return KRB5KDC_ERR_NOT_REQUIRED;
    }

    ret = get_server_hostname(request->server, &hostname);
    if (ret) {
        return ret;
    }

    if (!is_fqdn(hostname->data)) {
        ret = KRB5_KDC_FQDN_REQUIRED;
        goto cleanup;
    }

    target_realm = find_realm_by_hostname(hostname->data);
    if (!target_realm) {
        ret = KRB5_REALM_UNKNOWN;
        goto cleanup;
    }

    if (!target_realm->realm || !target_realm->realm[0]) {
        ret = KRB5_REALM_INVALID;
        goto cleanup;
    }

    ret = krb5_build_principal(request->context, krbtgt_princ, strlen(target_realm->realm), target_realm->realm,
                               strlen("krbtgt"), "krbtgt", 0, NULL);
    if (ret) {
        goto cleanup;
    }

cleanup:
    if (hostname) {
        krb5_free_data(request->context, hostname);
    }

    return ret;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_error_code ret = KRB5_KDC_ERR_NONE;
    krb5_principal server_principal = NULL;
    krb5_data *hostname = NULL;
    kdc_realm_t *target_realm = NULL;

    if (!request || !krbtgt_princ) {
        return KRB5_KDC_ERR_BADOPTION;
    }

    server_principal = request->client;
    if (!server_principal || !server_principal->name.name_string.len) {
        return KRB5_ERR_NO_TGT;
    }

    hostname = &server_principal->name.name_string.val[0];
    if (!hostname->length || !krb5_is_fqdn(hostname->data, hostname->length)) {
        return KRB5_KDC_ERR_ENTITY;
    }

    ret = kdc_find_realm_by_hostname(hostname, &target_realm);
    if (ret != 0 || !target_realm) {
        return KRB5_KDC_ERR_REALM;
    }

    if (target_realm->realm.length == 0) {
        ret = KRB5_KDC_ERR_BAD_REALM;
        goto cleanup;
    }

    ret = krb5_build_principal(krbtgt_princ, target_realm->context, target_realm->realm.length,
                               target_realm->realm.data, "krbtgt", hostname->length, hostname->data, NULL);
    if (ret != 0) {
        goto cleanup;
    }

cleanup:
    if (target_realm) {
        kdc_realm_free(target_realm);
    }

    return ret;
}
